zenuml
    title Diagnostic et réparation automatique d'une erreur Mermaid
    @Actor Agent
    App
    @Control Diagnostic
    @Entity Mermaid
    Agent->App: Saisit une ligne contenant une faute
    App->Diagnostic.diagnostiquer(code) {
        return candidats
    }
    App->Mermaid.verifierPropositions(candidats) {
        return reparationsValides
    }
    if (reparationsValides disponibles) {
        App->Agent: Propose le bouton Appliquer
    } else {
        App->Agent: Affiche la syntaxe attendue et un exemple du type
    }

C4Deployment
    title Déploiement de FUSAIN en environnement administratif
    Deployment_Node(poste, "Poste de travail Windows ou Linux", "Navigateur moderne") {
        Container(pwa, "Application FUSAIN (PWA)", "ES Modules + Service Worker", "Fonctionne hors ligne après le premier chargement")
        Container(ps1, "Serveur local autonome", "serveur-local.ps1", "Écoute sur 127.0.0.1:8090 sans droits admin")
    }
    Deployment_Node(intranet, "Serveur Intranet Ministère", "Debian 13 + paquet fusain-server") {
        Deployment_Node(nginx, "Nginx durci", "deploiement/nginx-fusain.conf") {
            Container(statique, "Fichiers statiques FUSAIN", "/usr/share/fusain", "En-têtes CSP, HSTS, X-Frame-Options et TLS")
        }
    }
    Rel(pwa, ps1, "Chargement hors ligne sur poste isolé", "HTTP localhost")
    Rel(pwa, statique, "Chargement et mise à jour sur intranet", "HTTPS / TLS")

railroad-ebnf-beta
    title "Référence d'une icône embarquée dans FUSAIN"
    icone_embarquee = jeu ":" identifiant ;
    jeu = "dsfr" | "illus" | "picto" ;
    identifiant = segment ( "-" segment )* ;
    segment = ( lettre | chiffre )+ ;

